// https://shaderpark.com/sculpture/-OsK9Xs40PPK4VdLRyrp
// by https://shaderpark.com/user/jsqvlC

let s = getSpace();

let sizeBase = input(0.5, 0.1, 1.2);
let sizeAmp = input(0.2, 0, 0.6);
let spacing = input(0.22, 0.05, 0.5);
let strength = input(5, 0, 12);
let drift = input2D(0, 0);

const lineCount = 6.0;

s.x += drift.x * 0.2;
s.y += drift.y * 0.2;

const sz = sizeBase + nsin(time) * sizeAmp;

const complexDiv = (a, b) => {
  const dm = 1.0 / (b.x * b.x + b.y * b.y);
  return dm * vec2(
    a.x * b.x + a.y * b.y,
    a.y * b.x - a.x * b.y
  );
};

function palette(t, a, b, c, d) {
  return a + b * cos(c * t + d);
}

let phi = 0.0;

for (let i = 0.0; i < lineCount; i += 1.0) {
  const xoff = (i - (lineCount - 1.0) * 0.5) * spacing;
  const a = vec2(s.x - xoff, s.y - sz);
  const b = vec2(s.x - xoff, s.y + sz);
  const q = complexDiv(a, b);
  phi += strength * atan(q.y, q.x) + 0.35 * i * sin(time * 0.9);
}

for (let i = 0.0; i < lineCount; i += 1.0) {
  const yoff = (i - (lineCount - 1.0) * 0.5) * spacing;
  const a = vec2(s.y - yoff, s.x - sz);
  const b = vec2(s.y - yoff, s.x + sz);
  const q = complexDiv(a, b);
  phi += strength * atan(q.y, q.x) + 0.35 * i * sin(time * 0.9);
}

phi = phi / (lineCount * 2.0);

const angle = sin(time * 0.84) * phi + 3.0 * sin(time);

const v = palette(
  angle,
  vec3(1, 0.1, 0.3),
  vec3(0.46, 0.22, 0.35),
  vec3(0.82, 0.84, 0.65),
  vec3(0.53, 0.23, 0.22)
);

color(v);
box(vec3(5.0, 2.0, 0.01));

// @title Noise Sphere
// @primaryButton settings

let radius = input(0.7, 0.1, 1.2);
let scale = 2.0;
let s = getSpace();
let n = 0.1 * noise(scale * s + time);
sphere(radius + n);

// @title Over
// @primaryButton settings
// @param opacity 1.0 0.0 1.0 0.001 "Opacity"

uniform sampler2D background;
uniform sampler2D foreground;
uniform float opacity;

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec4 bg = texture(background, uv);
  vec4 fg = texture(foreground, uv);
  float alpha = clamp(fg.a * opacity, 0.0, 1.0);
  float outAlpha = alpha + bg.a * (1.0 - alpha);
  vec3 rgb = (fg.rgb * alpha + bg.rgb * bg.a * (1.0 - alpha)) / max(outAlpha, 0.0001);

  fragColor = vec4(rgb, outAlpha);
}

// @title Feedback
// @primaryButton settings
// @param feedbackAmount 0.9 0.0 0.999 0.001 "Feedback"
// @param inputAmount 1.0 0.0 1.0 0.001 "Input"
// @param decay 0.98 0.0 1.0 0.001 "Decay"
// @param zoom 1.0 0.8 1.2 0.001 "Zoom"
// @param rotation 0.0 -0.2 0.2 0.0001 "Rotation"

uniform sampler2D source;
uniform sampler2D feedback;
uniform float feedbackAmount;
uniform float inputAmount;
uniform float decay;
uniform float zoom;
uniform float rotation;

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 p = uv - 0.5;
  float c = cos(rotation);
  float s = sin(rotation);
  p = mat2(c, -s, s, c) * p;
  p = p / max(zoom, 0.0001) + 0.5;

  vec4 current = texture(source, uv) * inputAmount;
  vec4 previous = texture(feedback, p) * decay * feedbackAmount;
  fragColor = max(current, previous);
}
